static int setting_default_uint8_to_bytes(uint8_t value, uint8_t *bytes, uint8_t len)
{
	if (len != 1) {
		return 0;
	}
	bytes[0] = value;
	return 1;
}

static int setting_default_uint16_to_bytes(uint16_t value, uint8_t *bytes, uint8_t len)
{
	if (len != 2) {
		return 0;
	}
	sys_put_le16(value, bytes);
	return 2;
}

static int setting_default_uint32_to_bytes(uint32_t value, uint8_t *bytes, uint8_t len)
{
	if (len != 4) {
		return 0;
	}
	sys_put_le32(value, bytes);
	return 4;
}

