static bool setting_uint8_t_in_range(const value_uint8 *setting, uint8_t *data, uint8_t len)
{
	if (len != 1) {
		return false;
	}
	uint8_t value = data[0];
	return value >= setting->min && value <= setting->max;
}

static bool setting_uint32_t_in_range(const value_uint32 *setting, uint8_t *data, uint8_t len)
{
	if (len != 4) {
		return false;
	}
	uint32_t value = sys_get_le32(data);
	return value >= setting->min && value <= setting->max;
}

static bool setting_bool_in_range(const value_bool *setting, uint8_t *data, uint8_t len)
{
	if (len != 1) {
		return false;
	}
	uint8_t value = data[0];
	return value >= setting->min && value <= setting->max;
}

static bool setting_uint16_t_in_range(const value_uint16 *setting, uint8_t *data, uint8_t len)
{
	if (len != 2) {
		return false;
	}
	uint16_t value = sys_get_le16(data);
	return value >= setting->min && value <= setting->max;
}

static bool setting_int32_t_in_range(const value_int32 *setting, uint8_t *data, uint8_t len)
{
	if (len != 4) {
		return false;
	}
	int32_t value = (int32_t)sys_get_le32(data);
	return value >= setting->min && value <= setting->max;
}

